import {bindProfilePhoto,profilePhotoPicker} from './profile-photo-picker.mjs';
import { t, translateError } from './i18n.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function showUserSettings(user,{modal,close,toast,onSave,logout}){modal(`<div class="eyebrow">${t("ACCOUNT SETTINGS","CÀI ĐẶT TÀI KHOẢN","계정 설정")}</div><h2>${t("User settings","Cài đặt người dùng","사용자 설정")}</h2><form id="user-settings-form">${profilePhotoPicker()}<label for="settings-name">${user.accountType==='nickname'?t("Change nickname","Thay đổi biệt danh","닉네임 변경"):t("Change name","Thay đổi tên","이름 변경")}</label><input id="settings-name" name="name" required minlength="${user.accountType==='nickname'?3:2}" maxlength="${user.accountType==='nickname'?30:100}" value="${esc(user.name)}"><label for="settings-address">${t("Change address or region","Thay đổi địa chỉ / khu vực","주소 또는 지역 변경")}</label><input id="settings-address" name="address" maxlength="200" autocomplete="street-address" value="${esc(user.address||'')}"><label for="settings-email">${t("Change email","Thay đổi email","이메일 변경")}</label><input id="settings-email" name="emailPending" type="email" maxlength="254" autocomplete="email" value="${esc(user.emailPending||user.email||'')}" placeholder="${t("you@example.com","ban@example.com","you@example.com")}"><p class="settings-email-note">${user.email?`${t("Current sign-in email:","Email đăng nhập hiện tại:","현재 로그인 이메일:")} <strong>${esc(user.email)}</strong>.<br>`:''}${t("Your new email is pending verification. Your current sign-in email still applies. Email verification is coming soon.","Email mới chỉ lưu dưới dạng yêu cầu chờ xác minh; chưa thay đổi email đăng nhập. Dịch vụ xác minh email đang được chuẩn bị.","새 이메일은 인증 대기 중입니다. 현재 로그인 이메일은 계속 사용할 수 있습니다. 이메일 인증 기능은 준비 중입니다.")}</p><label for="settings-phone">${t("Change phone number","Thay đổi số điện thoại","전화번호 변경")}</label><input id="settings-phone" name="phone" type="tel" maxlength="25" autocomplete="tel" value="${esc(user.phone||'')}" placeholder="+84 912 345 678">${user.designPreview?'<p class="settings-email-note">'+t("Preview mode: changes are stored in this browser.","Chế độ xây dựng: các thay đổi chỉ lưu trên trình duyệt.","미리보기 모드에서는 변경 사항이 이 브라우저에 저장됩니다.")+'</p>':''}<p id="settings-error" class="form-error" role="alert"></p><button class="dark">${t("Save changes","Lưu thay đổi","변경 사항 저장")}</button><button type="button" id="settings-logout" class="settings-logout">${t("↪ Sign out","↪ Đăng xuất","↪ 로그아웃")}</button></form>`);
document.querySelector('#settings-logout').onclick=()=>{document.body.classList.remove('broke-mode');close();logout();};
const form=document.querySelector('#user-settings-form');
const readPhoto=bindProfilePhoto(form,user.photo,user.name?.charAt(0)||'♡');
form.onsubmit=async event=>{event.preventDefault();const button=event.target.querySelector('.dark');button.disabled=true;const data={...Object.fromEntries(new FormData(event.target)),photo:await readPhoto()};try{let updated;if(user.designPreview){if(data.phone&&!/^\+?[\d\s().-]{8,25}$/.test(data.phone))throw Error(t("Check your phone number.","Vui lòng kiểm tra số điện thoại.","전화번호를 확인하세요."));updated={...user,...data};localStorage.setItem('debtfreelately-preview-settings',JSON.stringify(data));}else{const response=await fetch('/api/auth/profile',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const result=await response.json();if(!response.ok)throw Error(result.error||t("Could not save settings.","Không lưu được cài đặt.","설정을 저장할 수 없습니다."));updated=result.user;}onSave(updated);close();toast(data.emailPending&&data.emailPending!==user.email?t("Changes saved. Your new email is pending verification.","Đã lưu thông tin. Email mới đang chờ xác minh.","변경 사항을 저장했습니다. 새 이메일은 인증 대기 중입니다."):t("User settings saved.","Đã lưu cài đặt người dùng.","사용자 설정을 저장했습니다."));}catch(error){document.querySelector('#settings-error').textContent=translateError(error.message);button.disabled=false;}};
}

